1	import { notFound } from "next/navigation";
2	import { getHostingAccount } from "@/lib/actions-hosting";
3	import { StatusDot, Badge } from "@/components/ui/primitives";
4	import { HostingTabs } from "@/components/customer/hosting/HostingTabs";
5	
6	export const dynamic = "force-dynamic";
7	
8	export default async function HostingAccountPage({
9	  params,
10	  searchParams,
11	}: {
12	  params: Promise<{ id: string }>;
13	  searchParams: Promise<{ tab?: string; path?: string }>;
14	}) {
15	  const [{ id }, { tab, path }] = await Promise.all([params, searchParams]);
16	
17	  // getHostingAccount enforces owner-or-admin (throws) and returns null if missing.
18	  let account: Awaited<ReturnType<typeof getHostingAccount>> = null;
19	  try {
20	    account = await getHostingAccount(id);
21	  } catch {
22	    notFound();
23	  }
24	  if (!account) notFound();
25	
26	  const transitional = account.status === "PENDING" || account.status === "PROVISIONING";
27	
28	  return (
29	    <div>
30	      <div className="mb-6">
31	        <div className="flex flex-wrap items-center gap-3">
32	          <h1 className="page-title">{account.primaryDomain}</h1>
33	          <StatusDot status={account.status} />
34	          {account.sslActive && <Badge tone="green">HTTPS</Badge>}
35	        </div>
36	        <div className="mt-2 flex flex-wrap items-center gap-2">
37	          <Badge tone="slate">{account.planName}</Badge>
38	          <Badge tone="slate">PHP {account.phpVersion}</Badge>
39	          <a href="/dashboard/hosting" className="text-xs text-slate-500 hover:text-slate-300 hover:underline">← All hosting</a>
40	        </div>
41	      </div>
42	
43	      {transitional && (
44	        <div className="card mb-6 border-amber-500/30 text-sm text-amber-300">
45	          Your account is being set up — this usually takes under a minute. Refresh to see it come online.
46	        </div>
47	      )}
48	
49	      <HostingTabs account={account} initialTab={tab} initialPath={path} />
50	    </div>
51	  );
52	}
