18	/** The install target for a website card. */
19	function targetOf(w: HostingWebsiteView): SiteTarget {
20	  if (w.kind === "subdomain" && w.id) return { kind: "subdomain", id: w.id };
21	  if (w.kind === "addon" && w.id) return { kind: "addon", id: w.id };
22	  return { kind: "primary" };
23	}
