25	/**
26	 * Unified "Websites" panel: the account's primary site plus every subdomain and
27	 * addon domain, each as a card with its own actions — install WordPress / an app
28	 * onto THAT site, open its files, promote an addon domain to primary, or delete a
29	 * subdomain / addon. On-brand with the rest of the hosting panels.
30	 */
31	export function WebsitesPanel({ accountId }: { accountId: string }) {
32	  const [rows, setRows] = useState<HostingWebsiteView[] | null>(null);
33	  const [apps, setApps] = useState<{ slug: string; name: string; needsDb: boolean }[]>([]);
34	  const [busyKey, setBusyKey] = useState<string | null>(null);
35	  const [err, setErr] = useState("");
36	
37	  const refresh = useCallback(() => {
38	    listWebsites(accountId).then(setRows).catch(() => setRows([]));
39	  }, [accountId]);
40	
41	  useEffect(() => { refresh(); }, [refresh]);
42	  useEffect(() => { listAppCatalog().then(setApps).catch(() => {}); }, []);
43	
44	  // Poll while anything is settling (a new site provisioning, or an ACTIVE site
45	  // still waiting on its HTTPS certificate) so badges appear without a manual reload.
46	  useEffect(() => {
47	    if (!rows?.some((r) => r.status === "PENDING" || r.status === "DELETING" || (r.status === "ACTIVE" && !r.sslActive))) return;
48	    const t = setInterval(refresh, 5000);
49	    return () => clearInterval(t);
50	  }, [rows, refresh]);
51	
52	  async function doInstall(w: HostingWebsiteView, value: string) {
53	    if (!value) return;
54	    setBusyKey(w.key); setErr("");
55	    const r = value === "wordpress"
56	      ? await installWordPress(accountId, targetOf(w))
57	      : await installApp(accountId, value, targetOf(w));
58	    setBusyKey(null);
59	    if (r.error) setErr(r.error); else refresh();
60	  }
61	
62	  async function promote(w: HostingWebsiteView) {
63	    if (!w.id) return;
64	    if (!confirm(`Make ${w.hostname} your primary domain? Your main website (public_html) will answer on ${w.hostname}, and your old address will keep working as an alias.`)) return;
65	    setBusyKey(w.key); setErr("");
66	    const r = await setPrimaryHostingDomain(accountId, w.id);
67	    setBusyKey(null);
68	    if (r.error) setErr(r.error); else refresh();
69	  }
70	
71	  async function remove(w: HostingWebsiteView) {
72	    if (!w.id) return;
73	    if (!confirm(`Delete ${w.hostname}? Its files will be removed.`)) return;
74	    setBusyKey(w.key); setErr("");
75	    const r = w.kind === "subdomain" ? await deleteSubdomain(w.id) : await deleteAddonDomain(w.id);
76	    setBusyKey(null);
77	    if (r.error) setErr(r.error); else refresh();
78	  }
79	
80	  function openFiles(w: HostingWebsiteView) {
81	    window.location.href = `/dashboard/hosting/${accountId}?tab=files&path=${encodeURIComponent(w.fileManagerPath)}`;
82	  }
83	
84	  const kindLabel: Record<HostingWebsiteView["kind"], string> = { primary: "Primary", subdomain: "Subdomain", addon: "Addon domain" };
85	
86	  return (
87	    <div className="card">
88	      <div className="mb-4">
89	        <h3 className="font-semibold">Websites</h3>
90	        <p className="mt-1 text-sm text-slate-400">
91	          Every site on this account — your primary domain, subdomains and addon domains. Install WordPress or an app onto
92	          any one of them, open its files, or promote a domain to primary. Add new subdomains and addon domains from the{" "}
93	          <span className="text-slate-300">Domains</span> tab.
94	        </p>
95	      </div>
96	
97	      {err && <p className="mb-3 text-sm text-red-400">{err}</p>}
98	
99	      {rows === null ? (
100	        <p className="text-sm text-slate-500">Loading…</p>
101	      ) : (
102	        <ul className="space-y-3">
103	          {rows.map((w) => {
104	            const busy = busyKey === w.key;
105	            const settling = w.status === "PENDING" || w.status === "DELETING";
106	            return (
107	              <li key={w.key} className="rounded-xl border border-white/[0.06] bg-white/[0.02] p-4">
108	                <div className="flex flex-wrap items-start justify-between gap-3">
109	                  <div className="min-w-0">
110	                    <div className="flex flex-wrap items-center gap-2">
111	                      <a
112	                        href={w.sslActive ? `https://${w.hostname}` : `http://${w.hostname}`}
113	                        target="_blank"
114	                        rel="noreferrer"
115	                        className="truncate font-mono text-sm text-slate-100 hover:underline"
116	                      >
117	                        {w.hostname}
118	                      </a>
119	                      <Badge tone="slate">{kindLabel[w.kind]}</Badge>
120	                      {w.isFreeSubdomain && <Badge tone="brand">free subdomain</Badge>}
121	                      <StatusPill status={w.status} />
122	                      {w.sslActive ? <Badge tone="green">HTTPS</Badge> : <Badge tone="amber">HTTP</Badge>}
123	                    </div>
124	                    <div className="mt-1.5 flex flex-wrap items-center gap-x-4 gap-y-1 text-xs text-slate-500">
125	                      <span>App: <span className="text-slate-300">{w.installedApp ?? "None"}</span></span>
126	                      <span>PHP <span className="font-mono text-slate-300">{w.phpVersion}</span></span>
127	                      <span className="font-mono">{w.fileManagerPath}</span>
128	                    </div>
129	                  </div>
130	                </div>
131	
132	                <div className="mt-3 flex flex-wrap items-center gap-2">
133	                  {/* Install WordPress / an app onto THIS site */}
134	                  <label className="flex items-center gap-1.5 text-xs text-slate-400">
135	                    <span className="sr-only">Install app</span>
136	                    <select
137	                      className="input py-1 text-xs"
138	                      defaultValue=""
139	                      disabled={busy || settling}
140	                      onChange={(e) => { const v = e.target.value; e.currentTarget.value = ""; doInstall(w, v); }}
141	                    >
142	                      <option value="">{busy ? "Working…" : "Install app…"}</option>
143	                      <option value="wordpress">WordPress (auto)</option>
144	                      {apps.map((ap) => (<option key={ap.slug} value={ap.slug}>{ap.name}</option>))}
145	                    </select>
146	                  </label>
147	
148	                  <button className="btn-secondary px-2.5 py-1 text-xs" disabled={settling} onClick={() => openFiles(w)}>
149	                    Open files
150	                  </button>
151	
152	                  {w.canSetPrimary && (
153	                    <button className="btn-secondary px-2.5 py-1 text-xs" disabled={busy || settling} onClick={() => promote(w)}>
154	                      Set as primary
155	                    </button>
156	                  )}
157	
158	                  {(w.kind === "subdomain" || w.kind === "addon") && (
159	                    <button className="btn-danger px-2.5 py-1 text-xs" disabled={busy || settling} onClick={() => remove(w)}>
160	                      Delete
161	                    </button>
162	                  )}
163	                </div>
164	              </li>
165	            );
166	          })}
167	        </ul>
168	      )}
169	    </div>
170	  );
171	}
