7	/* A usage/quota tile with an optional progress bar. Extracted verbatim from the
8	 * old HostingClient so both the accounts list and the per-account page share it. */
9	export function QuotaTile({
10	  label,
11	  primary,
12	  bar,
13	  note,
14	}: {
15	  label: string;
16	  primary: string;
17	  bar?: { used: number; total: number };
18	  note?: string;
19	}) {
20	  const pct = bar && bar.total > 0 ? Math.min(100, Math.round((bar.used / bar.total) * 100)) : null;
21	  const full = pct !== null && pct >= 100;
22	  return (
23	    <div className="rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2.5">
24	      <p className="text-[11px] uppercase tracking-wide text-slate-500">{label}</p>
25	      <p className="mt-0.5 text-sm font-semibold text-slate-200">{primary}</p>
26	      {pct !== null && (
27	        <div className="mt-2 h-1.5 w-full overflow-hidden rounded-full bg-white/[0.06]">
28	          <div className={`h-full rounded-full ${full ? "bg-amber-400" : "bg-brand-400"}`} style={{ width: `${Math.max(4, pct)}%` }} />
29	        </div>
30	      )}
31	      {note && <p className="mt-1.5 text-[11px] text-slate-500">{note}</p>}
32	    </div>
33	  );
34	}
