927	/**
928	 * Validate an install target against an account (cross-tenant guard at the action
929	 * layer, mirrored again in the worker). For a subdomain/addon the row must exist,
930	 * belong to THIS account, and be ACTIVE. Returns the JSON `target` to embed in the
931	 * task payload (undefined for primary → the worker's back-compat default) plus a
932	 * short, DB-safe suffix that keeps each site's generated database name distinct.
933	 */
934	async function validateSiteTarget(
935	  accountId: string,
936	  target: SiteTarget | undefined,
937	): Promise<{ error?: string; payloadTarget?: { kind: string; id: string }; dbSuffix: string }> {
938	  const kind = target?.kind ?? "primary";
939	  if (kind === "primary") return { dbSuffix: "" };
940	  const id = "id" in (target ?? {}) ? String((target as { id: string }).id) : "";
941	  if (!id) return { error: "Choose a website to install onto.", dbSuffix: "" };
942	  if (kind === "subdomain") {
943	    const sub = await db.hostingSubdomain.findFirst({ where: { id, accountId }, select: { status: true } });
944	    if (!sub) return { error: "That subdomain isn’t part of this account.", dbSuffix: "" };
945	    if (sub.status !== "ACTIVE") return { error: "That subdomain is still being set up.", dbSuffix: "" };
946	    return { payloadTarget: { kind: "subdomain", id }, dbSuffix: randomBytes(3).toString("hex") };
947	  }
948	  if (kind === "addon") {
949	    const addon = await db.hostingAddonDomain.findFirst({ where: { id, accountId }, select: { status: true } });
950	    if (!addon) return { error: "That domain isn’t part of this account.", dbSuffix: "" };
951	    if (addon.status !== "ACTIVE") return { error: "That domain is still being set up.", dbSuffix: "" };
952	    return { payloadTarget: { kind: "addon", id }, dbSuffix: randomBytes(3).toString("hex") };
953	  }
954	  return { error: "Unknown install target.", dbSuffix: "" };
955	}

