export async function getHostingAppCredentials(
  accountId: string,
): Promise<{ site: string; app: string; url: string; adminUser: string; adminPassword: string; at: string }[]> {
  const user = await requireUser();
  await assertNotImpersonating();
  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { userId: true, primaryDomain: true } });
  if (!a) return [];
  if (a.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");

  // Resolve an install's target (primary / subdomain:<id> / addon:<id>) → the
  // website hostname it belongs to, so each credential is labelled with its site and
  // we can keep exactly ONE (the newest) per website — two WordPress installs on the
  // same site no longer show as two identical rows.
  const [subs, addons, rows] = await Promise.all([
    db.hostingSubdomain.findMany({ where: { accountId }, select: { id: true, fqdn: true } }),
    db.hostingAddonDomain.findMany({ where: { accountId }, select: { id: true, domain: true } }),
    db.hostingTask.findMany({
      where: { accountId, status: "DONE", kind: { in: ["WORDPRESS_INSTALL", "APP_INSTALL"] }, result: { not: null } },
      orderBy: { createdAt: "desc" },
      take: 50,
    }),
  ]);
  const subHost = new Map(subs.map((s) => [s.id, s.fqdn]));
  const addonHost = new Map(addons.map((d) => [d.id, d.domain]));

  const out: { site: string; app: string; url: string; adminUser: string; adminPassword: string; at: string }[] = [];
  const seen = new Set<string>(); // one credential per resolved site key (newest wins — rows are desc)
  for (const t of rows) {
    let p: { adminUser?: string; adminPassword?: string; url?: string; app?: string; name?: string } | null = null;
    let target: { kind?: string; id?: string } = {};
    try { p = JSON.parse(t.result || ""); } catch { p = null; }
    try { target = (JSON.parse(t.payload || "{}").target ?? {}) as { kind?: string; id?: string }; } catch { /* */ }
    if (!p || !p.adminUser || !p.adminPassword) continue;

    const siteKey = target.kind === "subdomain" && target.id ? `subdomain:${target.id}`
      : target.kind === "addon" && target.id ? `addon:${target.id}`
      : "primary";
    if (seen.has(siteKey)) continue;
    seen.add(siteKey);

    const site = target.kind === "subdomain" && target.id ? (subHost.get(target.id) ?? a.primaryDomain)
      : target.kind === "addon" && target.id ? (addonHost.get(target.id) ?? a.primaryDomain)
      : a.primaryDomain;

    out.push({
      site,
      app: p.app || p.name || (t.kind === "WORDPRESS_INSTALL" ? "WordPress" : "App"),
      url: p.url || "",
      adminUser: p.adminUser,
      adminPassword: p.adminPassword,
      at: t.createdAt.toISOString(),
    });
  }
  return out;
}

/**
 * Full hosting task history for the Logs tab — install/app/backup/PHP/domain/cron
 * operations with status + timestamps. Owner or admin. Read-only and secret-free:
 * unlike listHostingTasks it never returns `result` (which can carry a one-time app
 * password) and never mutates rows, so it's safe to poll and safe under impersonation.
 */
export async function listHostingTaskLog(
  accountId: string,
): Promise<{ id: string; kind: string; status: string; error: string | null; createdAt: string; updatedAt: string }[]> {
  const user = await requireUser();
  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { userId: true } });
  if (!a) return [];
  if (a.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  const rows = await db.hostingTask.findMany({
    where: { accountId, kind: { not: "INSTALL_DBTOOL" as Prisma.HostingTaskUncheckedCreateInput["kind"] } },
    orderBy: { createdAt: "desc" },
    take: 100,
  });
  return rows.map((t) => ({
    id: t.id,
    kind: t.kind,
    status: t.status,
    error: t.error,
    createdAt: t.createdAt.toISOString(),
    updatedAt: t.updatedAt.toISOString(),
  }));
}

