/* --------------------------------------------------- Website switcher --- */

/** URL/focus token for a website card: the row id, or "primary" for the main site. */
function siteParamOf(w: HostingWebsiteView): string {
  return w.id ?? "primary";
}

/**
 * A command-style search that lists every website on the account (primary +
 * subdomains + addon domains) and jumps to it in the Websites tab. This is the plan-
 * as-workspace navigator: the plan CONTAINS switchable websites, so finding one is a
 * search, not a domain-in-the-header assumption.
 */
function WebsiteSwitcher({ accountId, onPick }: { accountId: string; onPick: (siteParam: string) => void }) {
  const [sites, setSites] = useState<HostingWebsiteView[]>([]);
  const [q, setQ] = useState("");
  const [open, setOpen] = useState(false);
  const boxRef = useRef<HTMLDivElement>(null);

  useEffect(() => { listWebsites(accountId).then(setSites).catch(() => setSites([])); }, [accountId]);

  // Close the dropdown on an outside click.
  useEffect(() => {
    function onDoc(e: MouseEvent) { if (boxRef.current && !boxRef.current.contains(e.target as Node)) setOpen(false); }
    document.addEventListener("mousedown", onDoc);
    return () => document.removeEventListener("mousedown", onDoc);
  }, []);

  const needle = q.trim().toLowerCase();
  const matches = needle ? sites.filter((s) => s.hostname.toLowerCase().includes(needle)) : sites;
  const kindLabel: Record<HostingWebsiteView["kind"], string> = { primary: "Primary", subdomain: "Subdomain", addon: "Addon domain" };

  function pick(w: HostingWebsiteView) {
    onPick(siteParamOf(w));
    setOpen(false);
    setQ("");
  }

  return (
    <div ref={boxRef} className="relative max-w-md">
      <div className="flex items-center gap-2 rounded-xl border border-white/[0.08] bg-navy-900/70 px-3 py-2 backdrop-blur-md">
        <svg viewBox="0 0 20 20" fill="none" className="h-4 w-4 shrink-0 text-slate-500"><path d="M9 3a6 6 0 104.472 10.03l3.249 3.248a.75.75 0 101.06-1.06l-3.248-3.249A6 6 0 009 3z" fill="currentColor" /></svg>
        <input
          className="w-full bg-transparent text-sm text-slate-100 placeholder:text-slate-500 focus:outline-none"
          placeholder={`Search websites${sites.length ? ` (${sites.length})` : ""}…`}
          value={q}
          onFocus={() => setOpen(true)}
          onChange={(e) => { setQ(e.target.value); setOpen(true); }}
        />
      </div>
      {open && (
        <div className="absolute z-20 mt-1 max-h-72 w-full overflow-auto rounded-xl border border-white/[0.08] bg-navy-900/95 p-1 shadow-xl backdrop-blur-md">
          {matches.length === 0 ? (
            <p className="px-3 py-2 text-sm text-slate-500">No matching websites.</p>
          ) : (
            matches.map((w) => (
              <button
                key={w.key}
                type="button"
                onMouseDown={(e) => { e.preventDefault(); pick(w); }}
                className="flex w-full items-center justify-between gap-2 rounded-lg px-3 py-2 text-left hover:bg-white/[0.05]"
              >
                <span className="min-w-0 truncate font-mono text-sm text-slate-100">{w.hostname}</span>
                <span className="flex shrink-0 items-center gap-1.5">
                  {w.installedApp && <span className="text-[11px] text-slate-500">{w.installedApp}</span>}
                  <Badge tone={w.kind === "primary" ? "brand" : "slate"}>{kindLabel[w.kind]}</Badge>
                </span>
              </button>
            ))
          )}
        </div>
      )}
    </div>
  );
}

