/* ----------------------------------------------------------------- Logs --- */

const LOG_LABELS: Record<string, string> = {
  PHP_SWITCH: "PHP version change", WORDPRESS_INSTALL: "WordPress install", APP_INSTALL: "App install",
  BACKUP: "Backup", RESTORE: "Restore", CREATE_SUBDOMAIN: "Subdomain created", DELETE_SUBDOMAIN: "Subdomain removed",
  CREATE_ADDON_DOMAIN: "Addon domain added", DELETE_ADDON_DOMAIN: "Domain removed", CREATE_CRON: "Cron job created",
  DELETE_CRON: "Cron job removed", ENSURE_DBMGR: "Database manager", APPLY_PLAN_LIMITS: "Plan update",
  SET_PRIMARY_DOMAIN: "Primary domain change",
};

type LogRow = { id: string; kind: string; status: string; error: string | null; createdAt: string; updatedAt: string };

function LogsTab({ accountId }: { accountId: string }) {
  const [rows, setRows] = useState<LogRow[] | null>(null);

  useEffect(() => {
    let stop = false;
    const load = () => listHostingTaskLog(accountId).then((r) => { if (!stop) setRows(r); }).catch(() => { if (!stop) setRows([]); });
    load();
    const t = setInterval(load, 8000);
    return () => { stop = true; clearInterval(t); };
  }, [accountId]);

  const tone = (s: string) => s === "FAILED" ? "text-red-300" : s === "DONE" ? "text-emerald-300" : "text-amber-300";

  return (
    <div className="card">
      <div className="mb-4">
        <h3 className="font-semibold">Activity log</h3>
        <p className="mt-1 text-sm text-slate-400">
          Everything we&apos;ve done on this plan — app installs, backups, PHP changes, domain and cron operations — newest first.
        </p>
      </div>
      {rows === null ? (
        <p className="text-sm text-slate-500">Loading…</p>
      ) : rows.length === 0 ? (
        <p className="text-sm text-slate-500">No activity yet.</p>
      ) : (
        <ul className="divide-y divide-white/[0.06] overflow-hidden rounded-lg border border-white/[0.06]">
          {rows.map((t) => (
            <li key={t.id} className="flex flex-wrap items-center justify-between gap-2 bg-white/[0.02] px-3 py-2 text-sm">
              <div className="min-w-0">
                <span className="text-slate-200">{LOG_LABELS[t.kind] ?? t.kind}</span>
                {t.error && <span className="ml-2 text-xs text-red-300">{t.error}</span>}
              </div>
              <div className="flex shrink-0 items-center gap-3">
                <span className={`text-xs font-medium ${tone(t.status)}`}>{t.status.toLowerCase()}</span>
                <span className="text-xs text-slate-500">{new Date(t.createdAt).toLocaleString()}</span>
              </div>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

